	// Handle special cases first
	if tp == PurePayload {
		return "PurePayload"
	}
	if tp == TTHeaderFramed {
		return "TTHeaderFramed"
	}
	if tp == TTHeaderStreaming {
		return "TTHeaderStreaming"
	}
	if tp == GRPCStreaming {
