// String prints human readable information.
// For composite values, returns pipe-separated names of all set flags in ascending order.
func (tp Protocol) String() string {
	// Handle special cases first
	if tp == PurePayload {
		return "PurePayload"
	}
	if tp == TTHeaderFramed {
		return "TTHeaderFramed"
	}
	if tp == TTHeaderStreaming {
		return "TTHeaderStreaming"
	}
	if tp == GRPCStreaming {
		return "GRPCStreaming"
	}

	// Handle single flags
	switch tp {
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	}

	// Handle composite values by checking each bit
	var parts []string
	if tp&TTHeader != 0 {
		parts = append(parts, "TTHeader")
	}
	if tp&Framed != 0 {
		parts = append(parts, "Framed")
	}
	if tp&HTTP != 0 {
		parts = append(parts, "HTTP")
	}
	if tp&GRPC != 0 {
		parts = append(parts, "GRPC")
	}
	if tp&HESSIAN2 != 0 {
		parts = append(parts, "HESSIAN2")
	}
	if tp&TTHeaderStreaming != 0 {
		parts = append(parts, "TTHeaderStreaming")
	}
	if tp&GRPCStreaming != 0 {
		parts = append(parts, "GRPCStreaming")
	}

	if len(parts) > 0 {
		return strings.Join(parts, "|")
	}

	return Unknown
}

