// Unary-specific options: retry policies, circuit breaker, fallback
// These options only apply to unary (request-response) RPC calls.

// WithFailureRetry sets the failure retry policy for client, it will take effect for all methods by default.
// If one method has been set with a specific retry policy, the method-level policy will be used.
func WithFailureRetry(p *retry.FailurePolicy) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		if p == nil {
			return
		}
		di.Push(fmt.Sprintf("WithFailureRetry(%+v)", p))
		if o.RetryMethodPolicies == nil {
			o.RetryMethodPolicies = make(map[string]retry.Policy)
		}
		if o.RetryMethodPolicies[retry.Wildcard].BackupPolicy != nil ||
			o.RetryMethodPolicies[retry.Wildcard].MixedPolicy != nil {
			panic("BackupPolicy or MixedPolicy has been setup, cannot support Failure Retry at same time")
		}
		o.RetryMethodPolicies[retry.Wildcard] = retry.BuildFailurePolicy(p)
	}}
}

// WithBackupRequest sets the backup request policy for client, it will take effect for all methods.
func WithBackupRequest(p *retry.BackupPolicy) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		if p == nil {
			return
		}
		di.Push(fmt.Sprintf("WithBackupRequest(%+v)", p))
		if o.RetryMethodPolicies == nil {
			o.RetryMethodPolicies = make(map[string]retry.Policy)
		}
		if o.RetryMethodPolicies[retry.Wildcard].MixedPolicy != nil ||
			o.RetryMethodPolicies[retry.Wildcard].FailurePolicy != nil {
			panic("MixedPolicy or BackupPolicy has been setup, cannot support Failure Retry at same time")
		}
		o.RetryMethodPolicies[retry.Wildcard] = retry.BuildBackupRequest(p)
	}}
}

// WithMixedRetry sets the mixed retry policy for client, it will take effect for all methods.
func WithMixedRetry(p *retry.MixedPolicy) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		if p == nil {
			return
		}
		di.Push(fmt.Sprintf("WithMixedRetry(%+v)", p))
		if o.RetryMethodPolicies == nil {
			o.RetryMethodPolicies = make(map[string]retry.Policy)
		}
		if o.RetryMethodPolicies[retry.Wildcard].BackupPolicy != nil ||
			o.RetryMethodPolicies[retry.Wildcard].FailurePolicy != nil {
			panic("BackupPolicy or FailurePolicy has been setup, cannot support Mixed Retry at same time")
		}
		o.RetryMethodPolicies[retry.Wildcard] = retry.BuildMixedPolicy(p)
	}}
}

// WithRetryMethodPolicies sets method-level retry policies for client.
func WithRetryMethodPolicies(mp map[string]retry.Policy) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		if mp == nil {
			return
		}
		di.Push(fmt.Sprintf("WithRetryMethodPolicies(%+v)", mp))
		if o.RetryMethodPolicies == nil {
			o.RetryMethodPolicies = make(map[string]retry.Policy)
		}
		for m, p := range mp {
			o.RetryMethodPolicies[m] = p
		}
	}}
}

// WithSpecifiedResultRetry sets the ShouldResultRetry for client, it will take effect for all methods.
func WithSpecifiedResultRetry(rr *retry.ShouldResultRetry) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		if rr == nil || rr.ErrorRetry == nil {
			panic("ShouldResultRetry and ErrorRetry must not be nil")
		}
		di.Push(fmt.Sprintf("WithSpecifiedResultRetry({ErrorRetry:%T, RespRetry:%T})",
			rr.ErrorRetry, rr.RespRetry))
		o.RetryWithResult = rr
	}}
}

// WithFallback sets the fallback policy for client when RPC calls fail.
func WithFallback(fb *fallback.Policy) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithFallback(%+v)", fb))
		o.Fallback = fb
	}}
}

// WithCircuitBreaker sets the circuit breaker suite for client.
func WithCircuitBreaker(s *circuitbreak.CBSuite) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithCircuitBreaker")
		o.CBSuite = s
	}}
}

// WithContextBackup enables local-session context backup for backup requests.
// backupHandler allows you to maintain custom keys in your context when backup request launched.
// All built-in keys will be maintained automatically.
// If current context is already from a backup, backupHandler should return backup==false, which means not to backup further.
func WithContextBackup(backupHandler func(prev, cur context.Context) (ctx context.Context, backup bool)) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithContextBackup({%v})", reflect.TypeOf(backupHandler).String()))
		o.CtxBackupHandler = backupHandler
	}}
}
